UPDATE task_steps SET status = #{step.status}, started_at = #{step.startedAt}, finished_at = #{step.finishedAt},
  error_code = #{step.errorCode}, error_message = #{step.errorMessage}
WHERE task_id = #{step.taskId} AND stage = #{step.stage}
  AND status IN ('PENDING', 'RUNNING') AND status = #{expectedStatus}
